ejemplo_codigo:
calificacion = 85

if calificacion >= 90:
    print("Excelente")
elif calificacion >= 70:
    print("Aprobado")
else:
    print("Necesitas repasar")

edad = 20
tiene_credencial = True
if edad >= 18 and tiene_credencial:
    print("Puedes entrar")

pregunta_reactivo:
Si x = 10, ¿qué muestra este código?

if x > 5:
    print("Mayor")
else:
    print("Menor")

Si n = 0, ¿qué muestra este código?

if n > 0:
    print("positivo")
elif n < 0:
    print("negativo")
else:
    print("cero")
